/// <summary>A track id written as text, as int() reads it: 0 when it is not a number.</summary>
private static int TrackId(string text) =>
    int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int id) ? id : 0;

[TestCase]
public void A_version_1_save_keeps_its_best_laps()
{
    File.WriteAllText(_path, "{\"version\": 1, \"best\": {\"1\": 25.48, \"2\": 31.2}}");
    SaveData data = new SaveStore(_path).Read();
    AssertThat(data.Best["1"]).IsEqual(25480);
    AssertThat(data.Best["2"]).IsEqual(31200);
    AssertThat(data.Unlocked).IsEqual(3);
}

